package com.obysoft.faithOS.service;
import java.security.SecureRandom;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.entity.*;import com.obysoft.faithOS.repository.*;
@Service public class AttendanceDeviceService{private final AttendanceDeviceRepository devices;private final AttendanceDeviceAuditRepository audits;private final UserRepository users;private final AttendanceService attendance;private final CurrentChurchService current;private final PasswordEncoder passwords;private final SecureRandom random=new SecureRandom();private final Map<String,AttemptWindow> attempts=new ConcurrentHashMap<>();public AttendanceDeviceService(AttendanceDeviceRepository d,AttendanceDeviceAuditRepository a,UserRepository u,AttendanceService s,CurrentChurchService c,PasswordEncoder p){devices=d;audits=a;users=u;attendance=s;current=c;passwords=p;}
@Transactional public AttendanceCheckInResponse checkIn(String deviceId,String secret,DeviceCheckInRequest request,String remote){LocalDateTime now=LocalDateTime.now();String safeId=deviceId==null?"":deviceId.trim();if(rateLimited(remote,now))throw unauthorized();AttendanceDevice device=devices.findByDeviceId(safeId).orElse(null);if(device==null||!device.isActive()||(device.getLockedUntil()!=null&&device.getLockedUntil().isAfter(now))||secret==null||!passwords.matches(secret,device.getSecretHash())){if(device!=null){device.setFailedAttempts(device.getFailedAttempts()+1);if(device.getFailedAttempts()>=5)device.setLockedUntil(now.plusMinutes(15));devices.save(device);}audit(device,safeId,request.memberCode(),"AUTH_FAILURE",remote);recordFailure(remote,now);throw unauthorized();}device.setFailedAttempts(0);device.setLockedUntil(null);device.setLastUsedAt(now);devices.save(device);String code=request.memberCode().trim().toUpperCase();User user=users.findByChurchIdAndMemberCode(device.getChurch().getId(),code).orElse(null);if(user==null){audit(device,safeId,null,"MEMBER_NOT_FOUND",remote);throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Check-in could not be completed.");}AttendanceCheckInResponse result=attendance.checkIn(user,now,CheckInSource.DEVICE);audit(device,safeId,code,"SUCCESS",remote);return result;}
@Transactional public AttendanceDeviceResponse create(AttendanceDeviceRequest request){String secret=secret();AttendanceDevice d=new AttendanceDevice();d.setChurch(current.church());d.setName(request.name().trim());d.setDeviceId(UUID.randomUUID().toString());d.setSecretHash(passwords.encode(secret));d=devices.save(d);return response(d,secret);}@Transactional(readOnly=true)public List<AttendanceDeviceResponse> all(){return devices.findAllByChurchIdOrderByCreatedAtDesc(current.church().getId()).stream().map(d->response(d,null)).toList();}@Transactional public AttendanceDeviceResponse rotate(Long id){AttendanceDevice d=find(id);String secret=secret();d.setSecretHash(passwords.encode(secret));d.setFailedAttempts(0);d.setLockedUntil(null);return response(devices.save(d),secret);}@Transactional public void revoke(Long id){AttendanceDevice d=find(id);d.setActive(false);devices.save(d);}
private String secret(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private AttendanceDevice find(Long id){return devices.findByIdAndChurchId(id,current.church().getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Device not found."));}private AttendanceDeviceResponse response(AttendanceDevice d,String s){return new AttendanceDeviceResponse(d.getId(),d.getDeviceId(),d.getName(),d.isActive(),s);}private ResponseStatusException unauthorized(){return new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Device authentication failed.");}private void audit(AttendanceDevice d,String id,String code,String outcome,String remote){AttendanceDeviceAudit a=new AttendanceDeviceAudit();a.setDeviceId(id);a.setChurch(d==null?null:d.getChurch());a.setMemberCode(code);a.setOutcome(outcome);a.setRemoteAddress(remote);audits.save(a);}private boolean rateLimited(String k,LocalDateTime n){AttemptWindow w=attempts.get(k);return w!=null&&w.until.isAfter(n)&&w.count>=20;}private void recordFailure(String k,LocalDateTime n){attempts.compute(k,(x,w)->w==null||w.until.isBefore(n)?new AttemptWindow(1,n.plusMinutes(1)):new AttemptWindow(w.count+1,w.until));}private record AttemptWindow(int count,LocalDateTime until){}
}
